import"./chunk-2NFLSA4Y.js";var a={acceleratedMotion:{theory:{concept:"[[Uniformly accelerated motion is motion with a constant acceleration: the velocity changes by equal amounts in any equal time intervals.]]"},section:{definition:{title:"What is acceleration?",text:"[[Acceleration is the vector quantity that shows how quickly the velocity changes: a = \u0394v / \u0394t.]] It is measured in metres per second per second (m/s\xB2). An acceleration of 2 m/s\xB2 means the velocity changes by 2 m/s every second: starting from rest, 0, 2, 4, 6 m/s\u2026"},speedingUp:{title:"Speeding up",text:"When the acceleration points the same way as the motion, the speed grows: v = v\u2080 + a \xB7 t. A car starting from rest with a = 2 m/s\xB2 goes 10 m/s after 5 s and 20 m/s after 10 s. Because it keeps getting faster, it covers more and more distance every second."},braking:{title:"Braking",text:"[[When the acceleration points against the motion, the car slows down.]] It stops after t = v\u2080 / |a| and covers the stopping distance s = v\u2080\xB2 / (2 \xB7 |a|). Twice the speed means four times the stopping distance \u2014 that is why driving fast is dangerous."},marks:{title:"Growing gaps",text:"The dots on the road show where the bicycle was after every equal time interval. When the bicycle speeds up, the gaps grow; when it brakes, they shrink. Starting from rest, the distances covered in successive equal intervals grow as 1 : 3 : 5 : 7 \u2014 Galileo discovered this with balls rolling down a ramp."},graphs:{title:"Graphs of accelerated motion",text:"The speed\u2013time graph is a sloping straight line; its steepness is the acceleration. The area under it is the distance covered. The distance\u2013time graph is a curve (a parabola) that gets steeper and steeper while the bicycle speeds up. The acceleration\u2013time graph is a horizontal line."},example:{title:"In real life",text:"A family car reaches 100 km/h (about 28 m/s) in roughly 10 s, so its acceleration is about 2.8 m/s\xB2. Hard braking on a dry road gives about \u22128 m/s\xB2. A falling stone accelerates at 9.8 m/s\xB2 \u2014 that is the topic of free fall."},check:{title:"Check your understanding",text:"A car starts from rest with a = 3 m/s\xB2. How fast is it after 4 s? (12 m/s.) How far has it gone? (24 m.) A car at 20 m/s brakes at \u22125 m/s\xB2. How long until it stops, and how far does it go? (4 s, 40 m.) Try each answer in the simulation."}},formula:{acceleration:"Acceleration: change of speed divided by the time it took",speed:"Speed after time t",distance:"Distance covered after time t",timeless:"Speed and distance without the time",stopping:"Stopping distance when braking from v\u2080",average:"Average speed with constant acceleration"},variable:{acceleration:"Acceleration (negative when braking)",initialSpeed:"Starting speed",speed:"Speed at time t",time:"Time",distance:"Distance covered"},assumption:{point:"The bicycle is treated as a point \u2014 the front of its front wheel \u2014 so its size does not matter.",constant:"The acceleration is exactly constant and starts at once. Real riders, engines and brakes need a moment to reach full effect.",brakes:"A braking bicycle stops at v = 0 and stays there: brakes cannot drive it backwards.",scale:"The bicycle is drawn larger than scale so that it stays visible on long roads. Its wheels turn so that they do not slip on the road, so the bigger the drawing, the slower they turn. A wheel that spins too fast to follow is drawn as a blurred disc."},param:{initialSpeed:"Starting speed",acceleration:"Acceleration",roadLength:"Distance to the finish"},hint:{acceleration:"Positive: the bicycle speeds up. Negative: it brakes. Zero: uniform motion."},preset:{rest:"At rest",city:"City speed",highway:"Motorway speed",gentle:"Gentle start",sporty:"Sports car",brake:"Braking",emergency:"Emergency stop"},measure:{distance:"Distance covered",speedKmh:"Speed in km/h",remaining:"Distance to the finish",speedChange:"Change of speed since the start",averageSpeed:"Average speed"},view:{start:"Start",finish:"Finish",marksEvery:"Dots: bicycle position every {dt}",ghost:"without acceleration",ghostOption:"Bicycle without acceleration",crossed:"Finish in {time} at {speed}",stopped:"Stopped after {distance} in {time}",notMoving:"The bicycle does not move: give it a starting speed or a positive acceleration",timeLimit:"Time is up"},graph:{speed:"Speed against time",position:"Distance against time",acceleration:"Acceleration against time"},challenge:{fromRest:{title:"From zero to finish",description:"Start from rest and reach a finish at least 100 m away in 10 s or less.",hint:"s = a \xB7 t\xB2 / 2: for 100 m in 10 s the acceleration must be at least 2 m/s\xB2."},brake:{title:"Stop in time",description:"Start at 20 m/s or faster and stop before the finish line.",hint:"Brake harder (a more negative acceleration) or start more slowly."},constant:{title:"No acceleration",description:"Reach the finish with an acceleration of zero. What kind of motion is it?",hint:"Give the bicycle a starting speed and set a = 0."},stopAtLine:{title:"Right at the line",description:"Brake so that the bicycle stops less than 1 m before the finish line.",hint:"Stopping distance s = v\u2080\xB2 / (2 \xB7 |a|). Make it equal to the distance to the finish."},doubleSpeed:{title:"Double the speed",description:"Start moving and cross the finish at exactly twice your starting speed.",hint:"v\xB2 = v\u2080\xB2 + 2 \xB7 a \xB7 s with v = 2 \xB7 v\u2080 gives a = 3 \xB7 v\u2080\xB2 / (2 \xB7 s)."}}}},i={sim:a};export{i as default,a as sim};
